import React, { useEffect, useState, useContext } from 'react';
import { View, Text, TouchableOpacity, ActivityIndicator, FlatList, StyleSheet } from 'react-native';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import { DataContext } from '../context/DataContext';
// import ChatRoom from './ChatRoom';
import config from '../config'; // config 파일에서 IP 주소를 가져옴

const ChatList = () => {
    const [stompClient, setStompClient] = useState(null);
    const [chatsData, setChatsData] = useState([]);
    const { data } = useContext(DataContext);
    const { loginUser } = data || {}; // Ensure data is always an object
    const [loading, setLoading] = useState(true);
    const [currentChat, setCurrentChat] = useState(null);

    useEffect(() => {
        const id = loginUser?.email;
        if (id) {
            fetchChats(id);
        }

        const socket = new SockJS(`${config.BASE_URL}/ws`);
        const client = new Client({
            webSocketFactory: () => socket,
            debug: function (str) {
                console.log(`WebSocket debug: ${str}`);
            },
            reconnectDelay: 5000,
        });

        client.onConnect = () => {
            console.log('WebSocket connected');
            setStompClient(client);
            client.subscribe('/topic/chats', (msg) => {
                if (msg.body) {
                    console.log(`Received message: ${msg.body}`);
                    setChatsData(JSON.parse(msg.body));
                }
            });
        };

        client.activate();

        return () => {
            console.log('WebSocket disconnected');
            if (client) {
                client.deactivate();
            }
        };
    }, [loginUser]);

    const fetchChats = (id) => {
        console.log(`fetchChats - id: ${id}`);
        fetch(`${config.BASE_URL}/api/chats?userId=${id}`)
            .then((response) => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then((data) => {
                console.log(`fetchChats - data: ${JSON.stringify(data)}`);
                const sortedChats = data.sort((a, b) => new Date(b.time) - new Date(a.time));
                setChatsData(sortedChats);
                setLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching chat data:', error);
                alert(`Error fetching chat data: ${error.message}`);
                setLoading(false);
            });
    };

    const handleItemPress = (chatId, otherUserId, allPoints, sendedPoints) => {
        setCurrentChat({ chatId, otherUserId, allPoints, sendedPoints });
    };

    const renderChatListItem = ({ item }) => {
        console.log(`renderChatListItem - item: ${JSON.stringify(item)}`);
        const otherUserId = item.from_id === loginUser?.email ? item.to_id : item.from_id;

        console.log(
            `renderChatListItem - chatid: ${item.id}, otherUserId: ${otherUserId}, last_message: ${item.last_message}, chattime: ${item.time}`
        );

        return (
            <TouchableOpacity
                key={item.id}
                style={styles.listItem}
                onPress={() => handleItemPress(item.id, otherUserId, item.all_points, item.sended_points)}
            >
                <View>
                    <Text style={styles.itemText}>
                        <strong>{otherUserId}</strong>
                    </Text>
                    <Text style={styles.itemText}>{item.last_message}</Text>
                    <Text style={styles.itemText}>
                        총 금액: {item.all_points} 보낸 금액 : {item.sended_points}
                    </Text>
                    <Text style={styles.itemTime}>{new Date(item.time).toLocaleString()}</Text>
                </View>
            </TouchableOpacity>
        );
    };

    return (
        <View style={styles.container}>
            {currentChat ? (
                <ChatRoom
                    chatId={currentChat.chatId}
                    otherUserId={currentChat.otherUserId}
                    loginUserId={loginUser?.email}
                    allPoints={currentChat.allPoints}
                    sendedPoints={currentChat.sendedPoints}
                    goBack={() => setCurrentChat(null)}
                />
            ) : loading ? (
                <ActivityIndicator size="large" color="#0000ff" />
            ) : chatsData.length > 0 ? (
                <FlatList
                    data={chatsData}
                    renderItem={renderChatListItem}
                    keyExtractor={(item) => item.id.toString()}
                    contentContainerStyle={styles.list}
                />
            ) : (
                <View style={styles.noChat}>
                    <Text>채팅 내역이 없습니다</Text>
                    <Text>id: {loginUser?.email}</Text>
                </View>
            )}
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
        padding: 10,
    },
    list: {
        flexGrow: 1,
    },
    listItem: {
        padding: 15,
        borderBottomWidth: 1,
        borderBottomColor: '#ccc',
        marginBottom: 5,
    },
    itemText: {
        fontSize: 16,
    },
    itemTime: {
        fontSize: 12,
        color: '#999',
    },
    noChat: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
    },
});

export default ChatList;
